  _ = `Mặc định (Trung bình)`,
  _ = `Thông thường (Thấp)`,
  _ = `Loại nội dung phát sóng`,
  _ = `Mô tả việc nội dung này là phát sóng trực tiếp hay phát buổi quay sẵn. Với trường hợp thứ hai, thì đây là lần đầu nhìn thấy trên nền tảng hay chiếu lại.`,
