  _ = `Báo cáo sản phẩm này`,
  _ = `Vui lòng mô tả vì sao mục này lại vi phạm Điều khoản dịch vụ của Steam. Xin hãy đính kèm bất kì thông tin hoặc đường dẫn nào có liên quan. Sau khi đã gửi, bạn sẽ không thể rút lại báo cáo này.`,
  _ = `Lịch trình`,
  _ = `Công cụ lên lịch`,
