  _ = `Loại`,
  _ = `Mục đích`,
  _ = `Đấu đối kháng`,
  _ = `Đây là trận đấu tranh hạng giữa hai hoặc nhiều cá nhân/đội tuyển. Sau khi trận đấu kết thúc, bạn có thể cập nhật kết quả và đưa thông tin về người thắng cuộc.`,
  _ = `Phát sóng`,
  _ = `Dùng để mời gọi người dùng xem kênh phát trực tuyến trên Steam hoặc một nơi khác trong khoảng thời gian này.`,
  _ = `Chơi cùng`,
  _ = `Dùng để mời người dùng tham dự sự kiện trong khoảng thời gian này bằng cách khởi động trò chơi và tham gia`,
  _ = `Ngoài đời thực`,
  _ = `Được dùng khi việc lên lịch sẽ xảy ra và chỉ có thể truy cập được bởi người có mặt tại sự kiện; và không thể phát sóng trực tiếp được. Lưu ý: Bạn có thể sẽ không muốn đưa sự kiện này vào lịch vì người hâm mộ trên Steam cũng không thể tham gia.`,
  _ = `Bắt đầu lúc`,
  _ = `Chỉ định số phút khi sự kiện bắt đầu`,
  _ = `Phút`,
  _ = `Đề mục lịch này đã thay đổi so với mặc định. Bạn có chắc muốn xóa nó không? Hành động này không thể hoàn tác`,
  _ = `Chuỗi hiện tại`,
  _ = `Một "chuỗi" kết nối các sự kiện liên quan với nhau bằng ảnh và bảng màu nhận diện thương hiệu chung. Không bắt buộc phải có chuỗi để sự kiện được hiện lên lịch trình. Ví dụ: Chuỗi sự kiện cho sân khấu chính (Main Stage) hay tác phẩm nghệ thuật (Art).`,
  _ = `Chưa xác định chuỗi nào.`,
  _ = `Thêm chuỗi`,
  _ = `Thêm một chuỗi mới vào nhóm và sự kiện thương hiệu lên lịch trình.`,
  _ = `Xóa chuỗi`,
  _ = `Bạn có chắc muốn xóa chuỗi này?`,
  _ = `Chuỗi (%1$s) chưa dán nhãn`,
  _ = `Thêm sự kiện cụ thể cho chuỗi này. Chúng chỉ hợp lệ nếu được đăng công khai, bắt đầu và kết thúc trong khoảng thời gian đã lên lịch, cũng như khớp với loại hình sự kiện được phép tổ chức trong lịch trình.`,
  _ = `Thỏa thuận về sự kiện ưu đãi`,
  _ = `Trước khi sử dụng công cụ chỉnh sửa ưu đãi, bạn sẽ cần chấp thuận các yêu cầu sau:`,
  _ = `Tôi hiểu rằng trang ưu đãi phải mô tả rõ ràng nhóm hoặc cá nhân chịu trách nhiệm tổ chức chương trình ưu đãi hoặc sự kiện.`,
  _ = `Tôi hiểu rằng tôi không thể đảm bảo cho người tham gia một mức hiển thị cụ thể trên Steam, và tôi không thể tính phí cho vị trí trên trang.`,
  _ = `Tôi hiểu rằng Valve có quyền chỉnh sửa trang ưu đãi, bao gồm nhưng không giới hạn ở độ hiển thị của trò chơi hay chương trình phát sóng trên trang, văn bản hay hình ảnh mô tả sự kiện.`,
  _ = `Tôi hiểu rằng Valve sẽ chọn sự kiện nào để quảng bá trong cửa hàng Steam và sự kiện của tôi có thể không được quảng bá.`,
  _ = `Tôi hiểu rằng tôi chỉ có thể thêm trò chơi vào trang ưu đãi được nhà phát triển hoặc nhà phát hành cho phép. Nhà phát triển sẽ thấy trò chơi của họ được đưa vào chương trình ưu đãi ngay khi tôi thêm vào trang của mình tại đây.`,
  _ = `Tôi đồng ý với tất cả quy tắc nêu trong %1$s`,
  _ = `Xem %1$s để biết thêm chi tiết về việc thiết kế và tạo một trang ưu đãi.`,
  _ = `tài liệu`,
  _ = `Người liên hệ chính`,
  _ = `Nếu nhà phát triển, nhà phát hành, hoặc nhà báo có thắc mắc về sự kiện này, họ nên liên hệ ai?`,
  _ = `nhập tên`,
  _ = `nhập địa chỉ email`,
  _ = `Xem xét chỉ dẫn & thông tin liên hệ`,
  _ = `Đã xem xét chỉ dẫn và đồng ý vào ngày %1$s.`,
  _ = `Tài liệu ưu đãi dành cho nhà phát triển hoặc nhà phát hành`,
  _ = `Tài liệu ưu đãi loạt sản phẩm`,
  _ = `Tài liệu ưu đãi cho trang quảng bá lễ hội / hội nghị`,
  _ = `Tài liệu quảng bá theo khu vực`,
  _ = `Tài liệu quảng bá theo chủ đề`,
  _ = `Đã xem xét và chấp nhận chỉ dẫn.`,
  _ = `Vui lòng cung cấp tên và URL của người tổ chức sự kiện này. Thông tin này sẽ được hiển thị đầu trang ưu đãi. Thông tin này là bắt buộc và có thể chỉnh sửa bất cứ lúc nào.`,
  _ = `Nhà tổ chức sự kiện`,
  _ = `Cập nhật nhà tổ chức sự kiện`,
  _ = `Nhập thông tin nhà tổ chức`,
  _ = `Vui lòng nhập tên của chủ thể tổ chức sự kiện này. Liên kết có thể là trang chủ nhà sáng tạo trên Steam của bên tổ chức hoặc là một URL ngoài. Yêu cầu có tên tiếng Anh và tùy chọn bản địa hóa.`,
  _ = `Thông tin này sẽ hiển thị như sau trên trang ưu đãi của bạn:`,
  _ = `Thêm nhà tổ chức`,
  _ = `Tên nhà tổ chức`,
  _ = `URL`,
  _ = `Nhóm hình ảnh đã bản địa hóa`,
  _ = `Ảnh chủ đạo cho Nhóm hình ảnh đã bản địa hóa`,
  _ = `Đây sẽ là hình ảnh dự phòng mặc định nếu không có phiên bản đã bản địa hóa cho một ngôn ngữ mà người dùng đang muốn xem. Nó có thể là một hình ảnh không có bất kỳ ngôn ngữ nào, hoặc có ngôn ngữ chung cho các khách hàng của bạn.`,
  _ = `Nếu ảnh có chứa văn bản, bạn có thể tải các phiên bản hình ảnh đã bản địa hóa lên tại đây cho bất kỳ ngôn ngữ nào Steam hỗ trợ. Steam sẽ tự động hiện ảnh bản địa hóa phù hợp tới khách hàng.`,
  _ = `Tải lên các ảnh với tên file có đuôi là %1$s của Steam, để chúng tôi có thể tự động sắp xếp chúng vào đúng ngôn ngữ.`,
  _ = `Ngôn ngữ Web API`,
  _ = `Ảnh`,
  _ = `Dùng khu vực bên dưới để tải lên ảnh mới mà các sự kiện của bạn có thể truy cập. Bạn có thể kéo thả từ mục này hoặc nhấp để chèn ảnh cỡ đầy hoặc thumbnail vào bài đăng của mình.`,
