  _ = `Dải màu cho hình nền (dưới)`,
  _ = `Màu nhãn`,
  _ = `Dải màu cho hình nền (trên)`,
  _ = `Dải màu cho hình nền (dưới)`,
  _ = `Hình nền của mục`,
  _ = `Tải lên một ảnh để làm hình nền của mục này thay cho màu nền. Ảnh sẽ được nhân lên nếu kích cỡ quá nhỏ, không đủ lấp đầy không gian.`,
  _ = `Màu nền của mục`,
  _ = `Màu nền cho khối`,
  _ = `Xóa hình nền`,
  _ = `Đặt lại thiết lập hình nền`,
  _ = `Bỏ đặt tất cả tùy chọn cho hình nền hoặc màu nhãn.`,
  _ = `Tùy chỉnh viền`,
  _ = `Chiều rộng viền hình nền`,
  _ = `Chiều rộng có thể đặt từ 1 pixel tới %1$s pixel. Giới hạn được đặt để ngăn ảnh biểu trưng thu hẹp lại. Chúng tôi có thể giảm giá trị này khi hiển thị trên điện thoại.`,
  _ = `Màu viền hình nền`,
  _ = `Xóa chép đè ảnh biểu ngữ trang sản phẩm`,
  _ = `Chép đè ảnh biểu ngữ trang sản phẩm`,
  _ = `Chép đè ảnh biểu ngữ trang sản phẩm (di động)`,
  _ = `Đối với những trò chơi liệt kê trong mục, tùy chọn cung cấp một ảnh biểu ngữ cơ bản thay thế. Yêu cầu ảnh biểu ngữ trang cửa hàng sản phẩm ở đầu mục để chép đè chỉ cho các ứng dụng này.`,
  _ = `Là cửa hàng vật phẩm?`,
  _ = `Xếp ngẫu nhiên thứ tự các vật phẩm hàng đầu`,
  _ = `Xếp ngẫu nhiên thứ tự hiển thị các vật phẩm được chọn`,
