  _ = `Chọn tải lên một hoặc nhiều file để nhập văn bản bản địa hóa bao gồm tiêu đề và nội dung. Chúng tôi dùng định dạng file để xác định đây là XML hay CSV; với XML, mã ngôn ngữ API được đính vào cuối đuôi tên file trước định dạng để xác định file XML đó chứa ngôn ngữ nào. Bạn nên bắt đầu bằng cách xuất theo CSV hoặc XML để đảm bảo mình đang sử dụng đúng định dạng.`,
  _ = `Xuất ngôn ngữ hiện tại thành một file với định dạng được chọn. XML luôn tạo ra một file duy nhất với công cụ chỉnh sửa ngôn ngữ hiện tại. CSV sẽ xuất tất cả ngôn ngữ thành một file.`,
