  _ = `Sửa…`,
  _ = `Lựa các tùy chọn sau để khiến mục hỏi đáp này hiện tại cụm máy chủ mong muốn. Để hiển thị cũng cần phải đăng phiên bản trong ngôn ngữ được yêu cầu hoặc dự phòng phù hợp cho cụm máy chủ.`,
